import type { EquipCat, Equipment, Resource } from './schema';

// Rating keys per domain (see schema.ts). Ratings are passed positionally to keep entries compact.
const LAND_K = ['fire', 'at', 'prot', 'mob', 'aa'];
const AIR_K = ['a2a', 'a2g', 'stealth', 'avionics', 'range'];
const NAVAL_K = ['sur', 'asw', 'aaw', 'land', 'prot', 'stealth'];
const RES: Resource[] = ['steel', 'oil', 'chips', 'rare'];

function keysFor(cat: EquipCat): string[] {
  if (cat === 'fighter' || cat === 'attacker' || cat === 'heli') return AIR_K;
  if (cat === 'carrier' || cat === 'destroyer' || cat === 'frigate' || cat === 'submarine') return NAVAL_K;
  return LAND_K;
}

/**
 * e(id, name, cat, origin, year, tech, cost[M$], perLineYear, ratings[], needs[steel, oil, chips, rare], desc, partners?)
 */
function e(
  id: string, name: string, cat: EquipCat, origin: string, year: number, tech: string, cost: number, perLineYear: number,
  rv: number[], nv: number[], desc: string, partners?: string[],
): Equipment {
  const k = keysFor(cat);
  const r: Record<string, number> = {};
  k.forEach((key, i) => { r[key] = rv[i] ?? 0; });
  const needs: Partial<Record<Resource, number>> = {};
  RES.forEach((key, i) => { if (nv[i]) needs[key] = nv[i]; });
  const out: Equipment = { id, name, cat, origin, year, tech, cost, r, needs, perLineYear, desc };
  if (partners) out.partners = partners;
  return out;
}

